mapper.select:

		    SELECT
		      bst.BOOKSET_ID as booksetId,/**账套代码**/
		      bst.acct_subject_id acctSubjectId,/**核算主体代码**/
		      bst.START_DATE as vdate,/**账套开始日**/
		      bst.END_DATE as actMdate,/**账套结束日**/
		      bst.STANDARD_CCY as standardCcy,/**本位币**/
		      todo.BOOKSET_DATE as booksetDate,/**账套日期**/
		      todo.BOOK_DATE as bookDate,/**入账日期**/
		      todo.HAPPEN_DATE as happenDate, /**发生日期**/
		      /**add by leipeng 20181017 **/
		      bst.BOK_SPEC_MODE AS bokSpecMode , /**特殊核算模型*/
		      bst.ACCT_SUBJECT_TYPE as acctSubjectType, /**核算主体类别**/
		      bst.ACCT_MODE acctmode, /**核算方式*/
		      f.layering_id  layeringId,/**分层代码*/
		      f.bok_detail_id bokDetailId,/**账务明细代码*/
		      f.busi_id finprodId,/**业务明细代码_金融产品代码*/
		      f.busi_detail_type finprodType, /**业务明细类型*/
		      f.lev,/**级别序号*/
		      f.branch,/**分支序号*/
		      f.calendar_id calendarId,/**交易日历*/
		      f.cur_lev curLev/**当前级别*/
		    FROM BOK_BOOKSET bst
		    INNER JOIN BOK_BATCH_TASK_TODO todo ON bst.bookset_id = todo.bookset_id 
		    /***AND bst.ACCT_SUBJECT_TYPE = '01'**/
		    INNER JOIN bok_acct_layering_info f
		      ON bst.bookset_id = f.bookset_id 
			/**ON ASI.ACCT_SUBJECT_ID=BST.ACCT_SUBJECT_ID AND ASI.ACCT_SUBJECT_TYPE = BST.ACCT_SUBJECT_TYPE**/
			/**LEFT JOIN FIN_PRODUCT fin ON bst.ACCT_SUBJECT_ID = fin.FINPROD_ID AND fin.finprod_type = 'F16'**/
		WHERE  todo.SEQ_NO = #{seqNo}
			AND todo.BOOKSET_DATE = #{BOOKSET_DATE}
            AND todo.BOOK_DATE = #{BOOK_DATE}
            AND todo.HAPPEN_DATE = #{HAPPEN_DATE}
            AND todo.TASK_ID = #{taskId}  
            AND todo.IS_SUB_BOOKSET = #{IS_SUB_BOOKSET}
            /**AND fin.PROFIT_TYPE != '02'**/
